c8-3.solution:
#include <stdio.h>
#include <stdbool.h>

int main(void) {
    int n,a[20];
    if(scanf("%d",&n)!=1)return 1;
    for(int i=0;i<n;i++)if(scanf("%d",&a[i])!=1)return 1;
    int first=a[0];
    for(int i=0;i<n-1;i++)a[i]=a[i+1];
    a[n-1]=first;
    for(int i=0;i<n;i++)printf("%d ",a[i]);
    return 0;
}

