#include <stdio.h>
#include <stdbool.h>

int main(void) {
    int n,a[20],target,pos=-1;
    if(scanf("%d",&n)!=1)return 1;
    for(int i=0;i<n;i++)if(scanf("%d",&a[i])!=1)return 1;
